"""Sentinel ERM knowledge pack: concepts of enterprise risk management, EcoCash's own method, the mobile-money risk landscape, Zimbabwe's regulatory setting and
how to use Sentinel. It is general reference text written for this platform; EcoCash-specific facts (the GRC Policy, the register) come from approved documents and
live data, never from here. Entries that describe the outside world say so and point to the official source to check."""
import re

from . import matrix as mx

SRC = "Sentinel ERM knowledge pack"


def E(id, title, keys, text, refs=()):
    return {"id": id, "title": title, "keys": keys, "text": text, "refs": list(refs)}


ENTRIES = [
    E("risk", "Risk", ["risk", "what is risk", "define risk", "uncertainty"], "ISO 31000:2018 defines risk as the **effect of uncertainty on objectives**. The effect can be positive or negative, but in EcoCash's register a risk is written as an event that could stop an objective being met: *what could happen, why, and what it would cost*. Every risk in Sentinel has an owner, a cause, consequences, an inherent and a residual rating, controls and a treatment.", ["ISO 31000:2018"]),
    E("erm", "Enterprise risk management (ERM)", ["erm", "enterprise risk management", "coso", "iso 31000"], "ERM manages risk across the whole organisation, tied to strategy and performance. **COSO ERM (2017)** has five components: governance and culture; strategy and objective-setting; performance; review and revision; information, communication and reporting. **ISO 31000:2018** gives principles, a framework and a process. EcoCash's GRC Policy sets how Sentinel applies them: a common matrix, a control scale, appetite thresholds and Board reporting.", ["COSO ERM 2017", "ISO 31000:2018"]),
    E("process", "The risk management process", ["risk management process", "risk process", "steps", "identify analyse evaluate treat"], "The ISO 31000 process: **establish context** (objectives, scope, criteria) \u2192 **identify** risks (events, causes, consequences) \u2192 **analyse** (likelihood and consequence, controls) \u2192 **evaluate** against appetite \u2192 **treat** (avoid, mitigate, transfer, accept) \u2192 **monitor and review** continually, with **communication and consultation** throughout. In Sentinel: Risk Register and Assessment Studio (identify and analyse), Risk Appetite (evaluate), Actions and Issues (treat), KRI Monitor and Control Testing (monitor), Board Hub (communicate).", ["ISO 31000:2018 clause 6"]),
    E("register", "Risk register", ["risk register", "register"], "The risk register is the single record of risks: reference, statement, category, owner, inherent and residual rating, controls, treatment, status and history. EcoCash's register holds 33 risks from the ISMS and BCMS workbook (18 ISMS, 15 BCMS), grouped under seven strategic objectives, plus any risks entered since. Ratings move through draft, submitted, reviewed and approved with different people at each step.", ["GRC Policy"]),
    E("inherent_residual", "Inherent and residual risk", ["inherent", "residual", "inherent risk", "residual risk", "target risk", "after controls"], "**Inherent risk** is the level of risk with no controls; **residual risk** is what remains after the controls and treatments that actually work. The gap between them shows what the controls achieve. Sentinel rates both on the ranked matrix; the assessment workbook adds the residual risk rating (RRR) as a 0\u201325 value.", ["ISO 31000:2018", "COSO ERM 2017"]),
    E("appetite", "Risk appetite, tolerance and capacity", ["appetite", "tolerance", "capacity", "risk appetite", "risk tolerance", "target", "threshold", "above appetite", "outside appetite"], "**Appetite** is the amount of risk the Board is willing to accept to pursue its objectives; **tolerance** is the maximum deviation it will accept; **capacity** is the most the organisation could absorb. In the workbook the thresholds are **target {target}, appetite {appetite} and tolerance {tolerance}** on the residual risk rating (the GRC Policy text says 10, pending a decision). A risk above appetite needs a treatment plan; above tolerance needs Board attention.", ["COSO ERM 2017", "GRC Policy"]),
    E("matrix", "The ranked 5x5 risk matrix", ["matrix", "heat map", "ranked matrix", "5x5", "likelihood consequence", "rating scale", "risk rating"], "EcoCash uses the external auditor's **ranked 5x5 matrix**: a lookup of likelihood (1 rare to 5 almost certain) against consequence (1 insignificant to 5 major) that returns a rank 1\u201325, not a plain product. Bands: **Low 1\u20135, Medium 6\u201312, Significant 13\u201320, High 21\u201325**. Responses: Low is accepted and monitored; Medium is managed by the owner; Significant needs a dated, costed treatment plan; High needs the Board Risk Committee. See the Key tab in Risk Register.", ["External auditor recommendation", "GRC Policy"]),
    E("treatment", "Risk treatment options", ["treatment", "treat", "avoid", "mitigate", "transfer", "accept", "risk response", "options"], "Four classic options: **avoid** (stop the activity), **mitigate or reduce** (add or strengthen controls), **transfer or share** (insurance, outsourcing, contracts) and **accept** (informed decision, within appetite). The GRC control scale links the response to control effectiveness: a score of 1\u20133 is accepted, 4\u20136 is mitigated, 7\u201310 needs **immediate action**. Every treatment in Sentinel becomes an action with an owner and a date.", ["ISO 31000:2018 clause 6.5", "GRC Policy p.26"]),
    E("controls", "Controls and control effectiveness", ["control", "controls", "control effectiveness", "ice", "internal control effectiveness", "control scale", "effectiveness"], "A control is something that modifies risk: **preventive** (stops it), **detective** (finds it) or **corrective** (limits the damage). EcoCash rates each control's **Internal Control Effectiveness (ICE)** on a 1\u201310 scale (1 strong to 10 non-existent); the factor is the score divided by 10 and **effectiveness = 1 \u2212 factor**, with a target of 80%. Ratings should come from independent testing, not self-assessment, and a failed test raises an action.", ["GRC Policy p.26", "ISO 31000:2018"]),
    E("p2st2", "P2ST2: People, Process, Systems, Technology, Tools", ["p2st2", "taxonomy", "control taxonomy", "people process systems", "control categories"], "EcoCash classes every control under **People** (roles, training, culture), **Process** (procedures, approvals, reviews), **Systems** (applications and their built-in controls), **Technology** (infrastructure and security technology) and **Tools** (monitoring and supporting tools). The Control Taxonomy workbook is the library of 1,735 controls; risks use the ones that protect them, and a control used by several risks is counted once in the library.", ["EcoCash Control Taxonomy"]),
    E("loa_lor", "LoA, LoR, RRR, EMV", ["loa", "lor", "rrr", "emv", "level of assurance", "level of risk", "residual risk rating", "estimated monetary value", "emv-i", "emv-r", "emv-a"], "From the assessment workbook that feeds Power BI: **LoR** is the assessed level of risk (0\u20131); **LoA = 1 \u2212 LoR** is the assurance the controls give; **RRR = 25 \u00D7 (LoR + 0.04)** is the residual risk rating on a 0\u201325 scale; **EMV-i** is the estimated inherent monetary value, **EMV-r** the residual value, **EMV-a** the actual cost incurred. The portfolio targets are LoA 80% and LoR 20%.", ["Risk assessment workbook", "Performance Analytics"]),
    E("kri", "KRIs and KPIs", ["kri", "kpi", "key risk indicator", "key performance indicator", "indicator", "leading indicator", "amber", "red"], "A **KPI** measures performance against an objective; a **KRI** measures exposure to a risk and should be **leading**: it moves before the loss. Each has a target and amber and red thresholds, an owner and a frequency. A red KRI should open an action. Good KRIs are measurable, timely, owned and tied to a specific risk, for example SIM-swap requests per week, failed-transaction rate, agent float shortages, or overdue regulatory obligations.", ["ISO 31000:2018", "Sentinel Weekly KPI and KRI Monitor"]),
    E("three_lines", "The three lines model", ["three lines", "3 lines", "first line", "second line", "third line", "lines of defence", "internal audit"], "The IIA's Three Lines Model (2020): the **first line** (management and staff) owns and manages risk; the **second line** (risk, compliance and similar functions) provides expertise, challenge and monitoring; the **third line** (internal audit) gives independent assurance to the Board. Sentinel's separation of duties follows it: owners rate, the Risk Office reviews, a different approver signs off, and auditors see everything read-only.", ["IIA Three Lines Model 2020"]),
    E("owners", "Risk owner, control owner, action owner", ["risk owner", "control owner", "action owner", "ownership", "accountability", "who owns"], "The **risk owner** is accountable for the risk and its treatment; the **control owner** operates a control; the **action owner** delivers a treatment step by its date. One person can hold several roles but a control cannot be tested by its own owner, and an action cannot be closed by its owner or creator. Overdue actions escalate: owner on day 1, Head of Risk on day 3, MD on day 7.", ["GRC Policy", "Sentinel Actions and Issues"]),
    E("assessment", "Risk assessment", ["risk assessment", "assess", "identification", "analysis", "evaluation", "root cause", "consequence", "bow-tie"], "Assessment has three parts: **identification** (what can happen, why, with what consequences), **analysis** (how likely and how bad, and how well the controls work) and **evaluation** (compare with appetite, decide treatment). Good risk statements name the event, its cause and its consequence. Root-cause thinking (why could it happen?) and consequence thinking (what follows?) are often drawn as a bow-tie, with preventive controls on the left and corrective controls on the right.", ["ISO 31000:2018 clause 6.4", "ISO/IEC 31010"]),
    E("scenario", "Scenario analysis and stress testing", ["scenario", "stress test", "stress testing", "what if", "severe but plausible"], "Scenario analysis explores a **severe but plausible** event and its chain of effects (for example a three-day platform outage, or a sudden policy-rate change). Stress testing applies extreme values to key variables to see what breaks. Use them to test appetite, liquidity buffers, continuity plans and KRI thresholds, and record the assumptions.", ["ISO 31000:2018", "COSO ERM 2017"]),
    E("emerging", "Emerging risks and horizon scanning", ["emerging risk", "horizon scanning", "horizon", "emerging", "early warning", "radar"], "Emerging risks are developing threats whose effect is uncertain: new regulation, technology shifts, macro-economic changes, new fraud methods. **Horizon scanning** watches regulators, central banks and credible news so the Risk Office can assess early. Sentinel's Horizon watch does this on a schedule and prepares an impact analysis against the register; a person reviews every brief.", ["COSO ERM 2017"]),
    E("reporting", "Risk reporting to the Board", ["board", "board report", "risk committee", "reporting", "board pack", "risk report"], "The Board and its Risk Committee need a short, consistent view: the risk profile against appetite, the top risks, movement since last period, key indicators in alert, control assurance, overdue actions and decisions required. Sentinel builds the Board pack and the weekly KPI report from live data, so the numbers match the register.", ["GRC Policy", "COSO ERM 2017"]),
    E("bia", "Business impact analysis and recovery objectives", ["bia", "business impact analysis", "rto", "rpo", "mtpd", "recovery time", "recovery point", "maximum tolerable"], "A **business impact analysis** finds the activities that matter most and what an interruption costs over time. It sets the **MTPD** (maximum tolerable period of disruption), the **RTO** (recovery time objective: how fast service must return) and the **RPO** (recovery point objective: how much data loss is tolerable). Continuity plans, failover tests and exercises prove the objectives can be met.", ["ISO 22301:2019"]),
    E("bcms", "Business continuity (ISO 22301)", ["bcms", "iso 22301", "business continuity", "continuity", "disaster recovery", "crisis"], "ISO 22301 is the standard for a **business continuity management system**: understand the organisation, assess impacts, plan responses, exercise and improve. EcoCash's 15 BCMS risks in the workbook (BCMS 01\u201315) cover continuity plans, recovery capability, supplier dependency, communication and people. Untested plans conceal recovery gaps, so exercises and evidence matter more than documents.", ["ISO 22301:2019"]),
    E("isms", "Information security (ISO/IEC 27001)", ["isms", "iso 27001", "27001", "information security", "annex a", "statement of applicability"], "ISO/IEC 27001 specifies an **information security management system**. The 2022 edition's Annex A lists **93 controls in four themes**: organizational (37), people (8), physical (14) and technological (34). A Statement of Applicability says which apply and why. EcoCash's 18 ISMS risks (ISMS 01\u201318) cover governance, access, data, suppliers, incidents and continuity of security.", ["ISO/IEC 27001:2022"]),
    E("ai_governance", "AI governance (ISO/IEC 42001 and NIST AI RMF)", ["aims", "iso 42001", "42001", "nist ai rmf", "ai risk", "ai governance", "responsible ai", "bias", "model risk"], "ISO/IEC 42001:2023 specifies an **AI management system**; the NIST AI Risk Management Framework organises the work as **Govern, Map, Measure, Manage**. Typical AI risks: bias and unfairness, drift, lack of explainability, privacy, security (including prompt injection) and over-reliance. Sentinel keeps AI optional, logs everything, lets only a System Administrator switch it on, and leaves every decision to a named person.", ["ISO/IEC 42001:2023", "NIST AI RMF 1.0"]),
    E("incidents", "Incidents, loss events and near misses", ["incident", "loss event", "near miss", "operational loss", "loss data", "root cause analysis"], "An **incident** is an event that disrupted or could have disrupted operations; a **loss event** caused a financial loss; a **near miss** was caught in time. Recording them with category, cause, gross loss and recovery feeds the risk assessment (likelihood evidence), tests whether controls work and shows trends. Always trace to a root cause and a linked risk.", ["Basel operational risk event types", "ISO 31000:2018"]),
    E("fraud", "Fraud risk", ["fraud", "fraud risk", "social engineering", "agent fraud", "insider fraud", "account takeover", "scam"], "Fraud risk is loss through deception. For a mobile money business the main forms are **account takeover** (often through SIM swap or stolen credentials), **social engineering** of customers and agents, **agent fraud** (fake or colluding agents, float manipulation), **insider fraud** and **merchant or payment fraud**. Controls: strong identity checks, transaction limits and velocity rules, real-time monitoring, cooling-off periods after changes, staff screening and segregation of duties. At EcoCash fraud is overseen by the Head of Compliance and ML/CTF.", ["ACFE fraud tree", "FATF"]),
    E("simswap", "SIM-swap fraud", ["sim swap", "sim-swap", "sim replacement", "sim fraud", "number takeover"], "In a **SIM swap** a criminal gets the victim's number moved to a new SIM (by fraud at an outlet, by bribing staff or by impersonation), receives the one-time codes and drains the mobile wallet. Controls: identity verification and biometric checks at replacement, a cooling-off period and limits after a swap, alerts to the old device, out-of-band confirmation, monitoring replacement spikes by outlet, and sanctions for staff collusion. A rising KRI on swap requests is a leading signal.", ["GSMA mobile fraud guidance"]),
    E("float", "Agent float and liquidity", ["float", "e-float", "agent float", "agent liquidity", "cash out", "liquidity", "liquidity risk"], "Mobile money agents need **e-float** (electronic value) to cash customers in, and **cash** to pay them out. A shortage of either stops transactions and hurts trust. Drivers: rebalancing delays, seasonal demand, cash-in-transit problems, policy or rate changes that alter customer behaviour. Controls: float monitoring by agent, automated rebalancing triggers, super-agent and bank arrangements, and KRIs such as agent float shortages per day.", ["CGAP mobile money guidance"]),
    E("trust", "Trust account and settlement risk", ["trust account", "settlement", "settlement risk", "e-money", "customer funds", "reconciliation"], "Mobile money value is backed by funds held for customers, commonly in **trust or settlement accounts**. Risks include reconciliation breaks between the platform and bank balances, concentration with one bank, delays in settlement, and misuse of customer funds. Daily reconciliation, limits per bank, and independent review are the usual controls.", ["Central bank mobile money regulation (check the current directive)"]),
    E("outage", "Platform availability and operational resilience", ["outage", "platform outage", "availability", "downtime", "single point of failure", "data centre", "failover", "resilience", "operational resilience"], "A payments platform that is down stops every transaction. Resilience risks: single data-centre dependency, untested failover, capacity limits, change failures, and supplier outages. Controls: redundant sites, regular failover tests measured against the recovery objective, capacity monitoring, change control, and tested incident and communication plans. Availability and failed-transaction rate are the key indicators.", ["ISO 22301:2019", "Basel operational resilience principles"]),
    E("third_party", "Third-party and supplier risk", ["third party", "third-party", "supplier", "vendor", "outsourcing", "supplier risk", "concentration risk", "single source"], "Suppliers can fail, be breached or leave. Assess criticality, concentration (single-source dependency), financial health, security and continuity, put service levels and exit terms in contracts, test their continuity plans and monitor performance. Fourth-party dependencies (your supplier's suppliers) matter too.", ["ISO 31000:2018", "ISO/IEC 27036"]),
    E("aml", "AML/CFT: anti-money-laundering and counter-terrorist financing", ["aml", "cft", "money laundering", "terrorist financing", "kyc", "cdd", "customer due diligence", "suspicious transaction", "str", "sanctions", "fatf", "esaamlg"], "AML/CFT controls: **KYC and customer due diligence**, risk-based customer classification, **transaction monitoring**, **suspicious transaction reports** to the Financial Intelligence Unit, sanctions screening, record keeping and staff training. Standards come from the **FATF 40 Recommendations**; ESAAMLG is the FATF-style regional body for Eastern and Southern Africa that assesses member countries. Weak AML controls risk fines, loss of licence and reputational harm. At EcoCash AML/CTF and fraud sit under the Head of Compliance and ML/CTF.", ["FATF Recommendations", "ESAAMLG"]),
    E("data_protection", "Data protection in Zimbabwe", ["data protection", "cdpa", "cyber and data protection act", "personal data", "privacy", "data subject", "breach notification", "cross-border", "potraz", "dpo", "dpia"], "Zimbabwe's **Cyber and Data Protection Act [Chapter 12:07]** (2021) governs personal data; **POTRAZ** is the Data Protection Authority. It sets processing principles, data subject rights and duties for controllers and processors. **Sections 28 and 29** restrict transferring personal information outside Zimbabwe unless the destination gives adequate protection or a listed exception applies; commentary says POTRAZ should be notified. Commentary also reports a **24-hour breach notification** duty (section 19): confirm the exact wording with the DPO and the Act.", ["Cyber and Data Protection Act [Chapter 12:07]", "POTRAZ (potraz.gov.zw)"]),
    E("regulators", "Regulators and authorities in EcoCash's setting", ["regulator", "regulators", "rbz", "reserve bank", "potraz", "zimra", "fiu", "financial intelligence", "seca", "secz", "ipec", "who regulates"], "**Reserve Bank of Zimbabwe (RBZ)**: central bank; monetary policy, exchange control and the national payment system that mobile money operates in. **POTRAZ**: telecommunications regulator and Data Protection Authority. **Financial Intelligence Unit (FIU)**: receives suspicious transaction reports (it is hosted by the Reserve Bank). **ZIMRA**: tax and customs. **SECZ** and **IPEC** regulate securities and insurance and pensions (relevant to EcoCash's group insurance business). Always take current requirements from the regulator's own publications.", ["rbz.co.zw", "potraz.gov.zw", "zimra.co.zw"]),
    E("monetary", "Monetary policy and why it matters to EcoCash", ["monetary policy", "policy rate", "interest rate", "mpc", "money supply", "inflation", "exchange rate", "zig", "zimbabwe gold", "currency", "forex", "fx", "devaluation"], "Monetary policy (set by the RBZ's Monetary Policy Committee) works through the **policy interest rate**, money-supply and exchange-rate measures. For EcoCash a change can alter: **funding and liquidity costs**; **customer behaviour** (balances, cash-out, transaction values); **foreign-exchange exposure** on costs and suppliers; **fraud pressure** when conditions tighten; **regulatory requirements** that follow. Zimbabwe's currency is the ZiG (Zimbabwe Gold, introduced in 2024). Check the RBZ for the current decisions: Sentinel's Horizon watch and web search can bring them in with sources.", ["rbz.co.zw"]),
    E("fx_inflation", "Inflation and foreign-exchange risk", ["inflation", "fx risk", "foreign exchange", "price", "cost increase", "purchasing power"], "Inflation raises costs (salaries, energy, imported equipment) and erodes the value of balances; foreign-exchange movements affect imported costs, supplier contracts and reporting. Treatments: price and contract reviews, natural hedges (matching currency of income and cost), buffer budgets, scenario tests and KRIs on key cost lines. The weekly KPI report tracks inflation, fuel and exchange-rate lines.", ["COSO ERM 2017"]),
    E("cyber", "Cyber risk", ["cyber", "cyber risk", "ransomware", "phishing", "ddos", "malware", "vulnerability", "patch", "penetration test"], "Cyber risk is loss from attacks on systems and data: **phishing and credential theft**, **ransomware**, **denial of service**, **insider misuse**, **vulnerable or unpatched systems** and **supplier compromise**. Core controls: multi-factor authentication, least-privilege access, patching, network segmentation, endpoint and network monitoring, tested backups, security awareness and a rehearsed incident response. Indicators: critical vulnerabilities open, patch SLA, time to detect, MFA coverage.", ["ISO/IEC 27001:2022", "NIST CSF"]),
    E("regulatory", "Regulatory and compliance risk", ["compliance risk", "regulatory risk", "regulatory change", "obligation", "non-compliance", "penalty", "licence", "directive", "circular"], "Compliance risk is the chance of sanctions or loss from failing to meet laws, regulations and standards. Manage it with an **obligations register** (what each rule requires, who owns it, evidence), a **regulatory change** process (read new rules, assess impact, assign actions) and periodic compliance testing. Overdue regulatory actions and unreviewed directives are leading indicators.", ["ISO 37301 compliance management"]),
    E("people_risk", "People risk", ["people risk", "key person", "key-person", "skills", "attrition", "culture", "conduct"], "People risks include dependence on key individuals, skills gaps, high turnover, low engagement, poor conduct and weak risk culture. Controls: succession and cross-training, competence frameworks, clear accountability, whistle-blowing channels and consistent consequences for breaches.", ["ISO 31000:2018"]),
    E("reputation", "Reputational risk", ["reputation", "reputational risk", "brand", "customer trust", "trust"], "Reputational risk is loss of trust from stakeholders. It is usually a consequence of other risks (an outage, a fraud wave, a data breach, a regulatory finding), so it is best managed through those risks, through crisis communication plans and through honest, prompt customer communication.", ["ISO 31000:2018"]),
    E("strategic", "Strategic risk and the balanced scorecard", ["strategic risk", "strategy", "balanced scorecard", "bsc", "strategic objective", "perspective"], "Strategic risk threatens the objectives in the strategy. EcoCash's register is grouped under seven strategic objectives (SO 01 Business Performance, SO 02 Risk and Compliance, SO 03 Customer, SO 04 People, SO 05 Innovation, SO 06 Stakeholder Management and Sustainability, SO 07 Organisation Capacity). The Strategic Coverage Summary shows whether both the ISMS and the BCMS cover each objective.", ["EcoCash risk assessment workbook"]),
    E("financial", "Financial risk: credit, liquidity and market", ["financial risk", "credit risk", "market risk", "interest rate risk", "counterparty"], "**Credit risk**: a counterparty fails to pay. **Liquidity risk**: cash or float cannot meet obligations when due. **Market risk**: rates, exchange rates or prices move against you. **Counterparty risk** arises with banks and partners holding settlement balances. Limits, diversification, collateral, buffers and stress tests are the usual controls.", ["Basel principles"]),
    E("testing", "Control testing", ["control testing", "design effectiveness", "operating effectiveness", "independent test", "test a control", "retest"], "Test a control for **design** (would it work if operated as intended?) and **operating effectiveness** (did it work over the period, on a sample?). Testers must be independent of the owner. A failed test scores 7\u201310 and raises an action; retests are due in 6 months for rank 13 or above, otherwise in 12 months, with quarterly attestation by owners.", ["GRC Policy", "Sentinel Control Library and Testing"]),
    E("velocity", "Risk velocity, interdependence and correlation", ["velocity", "interdependence", "correlation", "interconnected", "cascade", "contagion"], "Some risks arrive fast (velocity), and risks rarely sit alone: a data-centre outage raises customer complaints, regulatory exposure and fraud opportunity at once. Map dependencies, rate the combined scenario, and set indicators that capture the chain, not just each link.", ["COSO ERM 2017"]),
    E("audit", "Risk-based internal audit", ["audit", "internal audit", "audit plan", "assurance", "audit universe"], "Internal audit uses the risk register to plan: higher residual risk and weaker control assurance get more audit attention. Findings become actions with owners and dates, and the Board audit committee tracks them to closure. Sentinel's Audit Workspace is planned for a later phase.", ["IIA Standards"]),
    # how to use Sentinel
    E("help_modules", "How Sentinel is organised", ["modules", "menu", "navigation", "where do i find", "what can sentinel do", "what modules", "how does sentinel work"], "The menu is grouped: **Command** (Command Center, Performance Analytics, Board Hub, Risk Appetite), **Risk** (Risk Register, Assessment Studio, AI Insights, Heat Map), **Controls and Assurance** (Control Library and Testing, Actions and Issues), **Events and Fraud** (Weekly KPI, KRI Monitor, Incidents and Losses) and **Intelligence** (Sentinel Copilot, AI Governance). Modules marked with a phase are planned. Use the search box at the top (Ctrl K) to jump to any page.", ["Sentinel"]),
    E("help_add_risk", "How to add or rate a risk", ["add a risk", "create a risk", "new risk", "how do i rate", "rate a risk", "enter a risk"], "Risk Register \u2192 **Add a risk**: write the statement, cause and consequences, choose category and owner, then set inherent and residual likelihood and consequence; the rank appears from the matrix and Sentinel says whether it is outside appetite. Save as draft, then **submit**: a reviewer and a different approver complete the workflow. To bring in many risks at once, import the assessment workbook (Assessment register tab).", ["Sentinel Risk Register"]),
    E("help_import", "How to import the risk assessment workbook", ["import workbook", "import the workbook", "upload workbook", "load the workbook", "redo the assessment"], "Risk Register \u2192 Assessment register \u2192 **Import the assessment workbook**. Sentinel previews what it found (risks, controls, exposure, the workbook's own LoA/LoR/RRR and any sheets that disagree with the Aggregation Sheet). Tick *Redo the assessment* to correct risks already in the register. Then load the Control Taxonomy workbook in Performance Analytics and run **Data quality** to reconcile the two.", ["Sentinel Risk Register"]),
    E("help_action", "How to create and close an action", ["create an action", "new action", "close an action", "overdue action", "escalation", "treatment action"], "Actions and Issues \u2192 **New action**: title, owner, due date, priority and the linked risk or incident. Closing needs evidence and an approver who is not the owner or creator. A revised deadline needs a different approver. Late actions escalate: owner on day 1, Head of Risk on day 3, MD on day 7. Risk treatments can be converted to actions in one step.", ["Sentinel Actions and Issues"]),
    E("help_reports", "How to produce the weekly report and Board pack", ["weekly report", "kpi report", "powerpoint", "board pack", "download report", "export", "presentation"], "Weekly KPI \u2192 **Download PowerPoint** builds the EcoCash weekly report with graphs and numbers; **Download Excel** gives the data. Performance Analytics \u2192 **Download PowerPoint** puts every dashboard page into a deck with editable charts. Board Hub builds the Board pack from live data.", ["Sentinel Weekly KPI", "Performance Analytics"]),
    E("help_ai", "How AI is switched on and who controls it", ["switch on ai", "turn on ai", "enable ai", "ai off", "who controls ai", "ask sentinel", "copilot settings", "ai mode", "kill switch"], "**Only a System Administrator** switches AI on or off or changes its mode (AI Governance). The built-in engine runs on this computer, needs no key and costs nothing; Claude can be added as an optional paid engine. Modes: Off, Assist (register and documents, no internet) and Advanced (adds web research and horizon scanning). The kill switch turns everything off at once. Everyone else can use the Copilot within their own permissions and see AI Governance in read-only form.", ["Sentinel AI Governance"]),
    E("help_mfa", "Two-step sign-in", ["two-step", "two step", "mfa", "multi-factor", "authenticator", "second factor", "2fa"], "Two-step sign-in asks for a 6-digit code from an authenticator app after the password. **Only a System Administrator switches it on or off**, for a whole role (Administration \u2192 Sign-in security) or for one person. A person who has it switched on is asked to set it up at once and receives recovery codes. If someone loses their phone an administrator resets it.", ["Sentinel Access Management"]),
]


def render(e):
    t = mx.THRESH
    return e["text"].format(target=t["target"], appetite=t["appetite"], tolerance=t["tolerance"]) if "{" in e["text"] else e["text"]


def lookup(text):
    """Entries whose keywords match the question, best first: [(score, entry)]."""
    q = " " + re.sub(r"[^a-z0-9\- ]+", " ", (text or "").lower()) + " "
    out = []
    for e in ENTRIES:
        s = 0
        for k in e["keys"]:
            kk = " " + k.lower() + " "
            if kk in q:
                s += 3 + len(k.split())
        if re.sub(r"[^a-z0-9 ]", " ", e["title"].lower()).strip() in q.strip() and len(e["title"]) > 3:
            s += 2
        if s:
            out.append((s, e))
    out.sort(key=lambda z: -z[0])
    return out
